/*getBuyerMdAmBudgetDepartmentListAll_v2*/ SELECT A.CODE AS DEPT_CD, A.TEXT1 AS DEPT_NM, A.TYPE_FLAG AS TYPE_FLAG FROM ICOMCOD2 A WHERE 1=1
AND A.COMPANY_CODE = #{st_buyer}
AND A.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND CODE LIKE '%'||#{st_req_dept_code}||'%'
AND UPPER(TEXT1) LIKE UPPER( '%'||#{st_req_dept_name}||'%')
AND A.TYPE = 'C001' AND A.TYPE_FLAG IN ('A', 'B') ORDER BY DEPT_NM

SELECT COUNT(*) OVER() AS TOTNUM, A.* FROM( SELECT /*selectBuyerMdAmBudgetDepartmentList*/ A.CODE AS DEPT_CD, A.TEXT1 AS DEPT_NM, B.CODE1 AS DEPT_CD2, -- 해당부서 DECODE(B.CODE2,NULL,'N','Y') AS DEPT_CD_BUD -- 예산부서 FROM ICOMCOD2 A , ICOMCOD3 B WHERE 1=1
AND A.COMPANY_CODE = #{st_buyer}
AND A.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND A.COMPANY_CODE = B.BUYER(+) AND A.TYPE = 'C001' AND A.CODE = B.CODE2(+) AND B.TYPE(+) = 'DTOD' AND A.TYPE_FLAG IN ('A', 'B')
AND B.CODE1(+) = #{st_dept_code}
) A ORDER BY DEPT_NM

SELECT COUNT(*) OVER() AS TOTNUM, A.* FROM( SELECT /*getBuyerMdAmBudgetDepartmentList_v2*/ A.CODE AS DEPT_CD, A.TEXT1 AS DEPT_NM, B.CODE1 AS DEPT_CD2, -- 해당부서 DECODE(B.CODE2,NULL,'N','Y') AS DEPT_CD_BUD -- 예산부서 FROM ICOMCOD2 A , ICOMCOD3 B WHERE 1=1
AND A.COMPANY_CODE = #{st_buyer}
AND A.COMPANY_CODE = #{SESSION_BUYER_CODE}
AND A.COMPANY_CODE = B.BUYER AND A.TYPE = 'C001' AND A.CODE = B.CODE2 AND B.TYPE = 'DTOD' AND A.TYPE_FLAG IN ('A', 'B')
AND B.CODE1 = #{st_dept_code}
) A ORDER BY DEPT_NM


