/*updateBuyerMdAmBudgetDepartmentList_v2*/
    UPDATE ICOMCOD2
    SET TYPE_FLAG = 'D'
   	WHERE 1=1
   	AND COMPANY_CODE = #{st_buyer}
   	AND TYPE = 'C001'
   	AND CODE = #{DEPT_CD}


/*delBuyerMdAmBudgetDepartmentList_v2*/
    DELETE FROM ICOMCOD2
   	WHERE 1=1
   	AND COMPANY_CODE = #{st_buyer}
   	AND TYPE = 'C001'
   	AND CODE = #{DEPT_CD}
   	AND TYPE_FLAG = 'B'


        /*saveBuyerMdAmBudgetDepartmentList_v3*/
            MERGE INTO ICOMCOD2
            USING DUAL
            ON( COMPANY_CODE = #{st_buyer}
            AND TYPE = 'C001'
            AND CODE = #{DEPT_CD})
            WHEN MATCHED THEN
			UPDATE 
			SET TEXT1 = #{DEPT_NM}
            ,TEXT2 = #{DEPT_NM}	
            WHEN NOT MATCHED THEN
			INSERT (
			TYPE
            ,CODE
            ,COMPANY_CODE
            ,TEXT1
            ,TEXT2
            ,FLAG
            ,ADD_DATE
            ,TYPE_FLAG)
            VALUES
            ('C001'
            ,#{DEPT_CD}
            ,#{st_buyer}
           	,#{DEPT_NM}
           	,#{DEPT_NM}
           	,'Y'
           	,TO_CHAR(SYSDATE,'YYYYMMDD')
           	,'B'
           	)


